import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;import java.util.*;import java.math.*;import java.io.*;import java.nio.charset.StandardCharsets;class ContractTest{static String capture(Runnable action){PrintStream previous=System.out,oldErr=System.err;ByteArrayOutputStream bytes=new ByteArrayOutputStream();try(PrintStream out=new PrintStream(bytes,true,StandardCharsets.UTF_8)){System.setOut(out);System.setErr(out);action.run();}finally{System.setOut(previous);System.setErr(oldErr);}return bytes.toString(StandardCharsets.UTF_8).replace("\r\n","\n");}@Test void newClassResetsStateAndRefills(){Object q=TaskBinding.newQueue();assertEquals("",capture(()->{TaskBinding.reset(q);TaskBinding.put(q,'A');TaskBinding.put(q,'B');assertEquals('A',TaskBinding.get(q));TaskBinding.reset(q);TaskBinding.put(q,'X');TaskBinding.put(q,'Y');assertEquals('X',TaskBinding.get(q));assertEquals('Y',TaskBinding.get(q));}));assertEquals("Очередь пуста\n",capture(()->assertEquals('\0',TaskBinding.get(q))));}}
